use std::time::Duration;
use std::collections::VecDeque;

use crate::context::service::ContextService;
use crate::context::model::{ContextRequest, SourceIdentity, EgressPolicy};
use crate::store::ladybug::LadybugStore;
use crate::traits::MemoryPayload;
use serde_json::json;

/// Collects execution times and computes p95 latency.
fn collect_latencies<F, T>(label: &str, iterations: usize, f: F) -> Vec<Duration>
where
    F: Fn() -> T,
{
    let mut latencies = Vec::with_capacity(iterations);
    let start = std::time::Instant::now();

    for i in 0..iterations {
        let _ = f();
        if i % 100 == 0 || i == iterations - 1 {
            latencies.push(start.elapsed());
        }
    }

    latencies
}

/// Calculates p95 from a sorted list of durations.
fn calculate_p95(latencies: &[Duration]) -> Duration {
    if latencies.is_empty() {
        return Duration::ZERO;
    }
    let mut sorted = VecDeque::from(latencies.to_vec());
    sorted.make_contiguous();
    sorted.sort();
    let index = (latencies.len() as f64 * 0.95).ceil() as usize - 1;
    sorted[index]
}

#[test]
fn benchmark_context_plan_p95() {
    // Benchmark ContextService::plan (stub returns empty plan instantly)
    let latencies = collect_latencies("ContextService::plan", 500, || {
        let mut service = ContextService::new();
        let request = ContextRequest {
            session_id: "bench".into(),
            context_epoch: 1,
            event_id: "evt".into(),
            trigger: "file_touch".into(),
            source: SourceIdentity::default(),
            policy: EgressPolicy::default(),
        };
        service.plan(request)
    });
    let p95 = calculate_p95(&latencies);
    eprintln!("ContextService::plan p95: {:?}", p95);
    // Just verify it runs without panicking; exact value will be recorded in ledger
    assert!(p95 < Duration::from_millis(500), "plan p95 unexpectedly high");
}

#[test]
fn benchmark_upsert_p95() {
    let temp_dir = std::env::temp_dir().join("benchmark_upsert2");
    std::fs::remove_dir_all(&temp_dir).ok();
    std::fs::create_dir_all(&temp_dir).unwrap();
    let store_path = temp_dir.join("store2.lbug");

    let mut store = LadybugStore::for_testing(store_path.to_string_lossy().to_string(), 4).unwrap();
    let _ = tokio::runtime::Runtime::new().unwrap().block_on(store.init("BenchmarkUpsert2"));

    let latencies = collect_latencies("LadybugStore::upsert", 200, || {
        let payload = MemoryPayload {
            content: "benchmark content".to_string(),
            user_id: "bench".to_string(),
            memory_type: "rule".to_string(),
            agent_name: None,
            location: "tests/benchmark/context_plan_latency.rs".to_string(),
            location_lines: "0".to_string(),
            metadata: json!({
                "test_id": 1,
                "source": "benchmark",
            }),
        };
        let _ = tokio::runtime::Runtime::new().unwrap().block_on(
            store.upsert(
                "BenchmarkNamespace",
                "benchmark_memory_001",
                vec![0.1; 4],
                payload,
            )
        );
    });
    let p95 = calculate_p95(&latencies);
    eprintln!("LadybugStore::upsert p95: {:?}", p95);
    assert!(p95 < Duration::from_millis(500), "upsert p95 unexpectedly high");
}